SourceCode.Declaration:
/// <summary>
/// CB202_SalesQuotaMinMax
/// </summary>
final class METAgreementLineSearchCommitmentType_VendorCategoryProductVolume extends METAgreementLineSearchCommitmentType
{
    VendAccount vendAccount;

}

Method.Source:
/// <summary>
/// Bypass the super so no range on itemId is added
/// using the sales unit.
/// </summary>
/// <param name="_agreementLineQbds">The QueryBuildDataSource to which the range is added.</param>
void agreementLineAddRange(QueryBuildDataSource _agreementLineQbds)
{
    // no filter on itemId as we are using Category
    _agreementLineQbds.addRange(fieldNum(AgreementLine, Category)).value(SysQuery::valueNot(0));
}

/// <summary>
/// Initializes the vendor account by retrieving it from the item coverage setup,
/// considering the site and warehouse combination specified on the sales order.
/// </summary>
protected void initialise()
{
    super();

    // SG 266541
    // Retrieve the vendor account associated with the item by checking the Item Coverage setup for the item,
    // considering the site and warehouse combination specified on the Sales Order.
    InventDim reqCovInventDim;
    reqCovInventDim.InventSiteId = inventDim.InventSiteId;
    reqCovInventDim.InventLocationId = inventDim.InventLocationId;

    ReqCovInventDimId covInventDimId = InventDim::findOrCreate(reqCovInventDim).inventDimId;
    ReqItemTable reqitemTable = ReqItemTable::find(itemId, covInventDimId);

    if (reqitemTable && reqitemTable.ItemCovFieldsActive)
    {
        vendAccount = reqitemTable.VendId;
    }
}

/// <summary>
/// Validates the found agreement line to make sure the product category is a descendant of _agreementLine.Category
/// AND that the vendor account on the product category matches the vendor account on the item coverage.
/// </summary>
/// <param name = "_agreementLine"><c>AgreementLine</c> record</param>
/// <returns>True if validate; otherwise, false.</returns>
protected boolean validateAgreementLine(AgreementLine _agreementLine)
{
    boolean ret = false;

    EcoResProductCategory productCategory = EcoResProductCategory::findByItemIdCategoryHierarchyRole(itemId, EcoResCategoryHierarchyRole::getHierarchiesByRole(EcoResCategoryNamedHierarchyRole::RetailSpecialGroup).NamedCategoryHierarchyRole);

    boolean isDescendant = EcoResCategory::isDescendant(productCategory.Category, _agreementLine.Category, true);

    if (isDescendant && EcoResCategory::find(_agreementLine.Category).METVendAccount == vendAccount)
    {
        return true;
    }

    return ret;
}

/// <summary>
/// Search method
/// </summary>
/// <returns><c>METAgreementLineSearchResult</c> object</returns>
public METAgreementLineSearchResult search()
{
    METAgreementLineSearchResult result;

    // only run the Vendor category value commitment search if we have a vendor account
    if (vendAccount)
    {
        result = super();
    }

    return result;
}

/// <summary>
/// Gets the commitment type for this agreement line search.
/// </summary>
/// <returns>
/// The <c>CommitmentType::METVendorCategoryProductVolume</c> value indicating the commitment type is based on Vendor category value commitment.
/// </returns>
protected CommitmentType getCommitmentType()
{
    return CommitmentType::METVendorCategoryProductVolume;
}
